      },
      {
        "event_id": "lite_evt_00097",
        "explanation": "The interim checklist omitted clean/dry dressing care, off-loading, and avoidance of wound manipulation.",
        "quote": "盯体温、渗水、意识变化，任何一条不对马上喊人。"
      }
    ],
